/**
 * > The notes below are not from Synchra. They were added by https://github.com/Bluscream/synchra-api.
 *
 * **A notice carries its content somewhere else.** Normally the rendered content is the ordered,
 * typed list in `message_parts`. For a notice — a gift, a sub, a raid — `message_parts` is
 * **empty** and the content is in `notice_message_parts` instead.
 *
 * Reading only `message_parts` therefore draws every gift as a blank row, and because gifts
 * cluster, a busy stream's chat log appears to go dead. Read whichever list is non-empty.
 *
 * Deciding whether a notice counts as a "message" or an "event" in your own UI is worth doing
 * deliberately: the API delivers it through `chat-messages`, not through `activities`, so a
 * notification filter split along those lines puts gifts on the chat side.
 */
export interface ChatMessage {
  access_level: Enums.TAccessLevel;
  badges: ChatMessageBadge[];
  /**
   *
   * Format: `uuid`.
   */
  channel_id: string;
  channel_provider_chat_id: string | null;
  channel_provider_stream_id: string | null;
  /**
   *
   * An ISO 8601 timestamp. See {@link IsoDateTime}.
   */
  created_at: IsoDateTime;
  deleted_at: IsoDateTime | null;
  deleted_by_display_name: string | null;
  deleted_by_name: string | null;
  deleted_by_provider_viewer_id: string | null;
  /**
   *
   * Format: `uuid`.
   */
  id: string;
  message_parts: ChatMessagePart[];
  /**
   * > The notes below are not from Synchra. They were added by https://github.com/Bluscream/synchra-api.
   *
   * The content of a notice — a gift, a sub, a raid. When this is non-empty, `message_parts` is
   * **empty**, and this is what there is to render.
   */
  notice_message_parts: ChatMessagePart[];
  outgoing_group_id: string | null;
  parent: ChatMessageParent | null;
  parent_provider_thread_id: string | null;
  provider:
    | 'twitch'
    | 'discord'
    | 'youtube'
    | 'spotify'
    | 'tiktok'
    | 'x'
    | 'rumble'
    | 'kick'
    | '7tv'
    | 'betterttv'
    | 'frankerfacez'
    | 'streamelements'
    | 'streamlabs'
    | 'ttsmonster'
    | 'elevenlabs'
    | 'amazon_polly'
    | 'obs_remote'
    | 'kofi'
    | 'fourthwall'
    | 'patreon'
    | 'owncast';
  provider_channel_id: string;
  provider_logo_variant: string | null;
  provider_message_id: string;
  provider_viewer_id: string;
  source_provider_channel_display_name: string | null;
  source_provider_channel_id: string | null;
  source_provider_channel_name: string | null;
  sub_type: string | null;
  type: 'message' | 'notice' | 'status' | 'automod';
  updated_at: IsoDateTime | null;
  viewer_color: string | null;
  viewer_created_at: IsoDateTime | null;
  viewer_display_name: string;
  /**
   * > The notes below are not from Synchra. They were added by https://github.com/Bluscream/synchra-api.
   *
   * A handle, not a URL — the API carries no link to a viewer's profile, and building one is
   * per-provider. YouTube is addressed by channel id (`provider_viewer_id`), everyone else by
   * handle, and some providers have no public profile page at all.
   */
  viewer_name: string;
  /**
   * > The notes below are not from Synchra. They were added by https://github.com/Bluscream/synchra-api.
   *
   * **Present for some providers, null for others** — filled for TikTok, not for Twitch or
   * YouTube. Do not treat an absence as "this viewer has no picture"; it usually means Synchra
   * did not resolve one. The picture is available from
   * `GET /api/2/channels/{channel_id}/viewers/{provider}/{provider_viewer_id}/info`.
   */
  viewer_profile_picture_url: string | null;
}

